insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('90780c49-52f4-5cff-bd79-74dc6230e838', 'rg8-text-structure-p01', (select id from public.skills where slug = 'read-g8-text-structure'), null,
        '6-8', $q$How a Water Tower Works$q$, $q$Many towns have a tall tank standing on legs or a thick column near the edge of town. It may look like a giant mushroom or a lollipop, but it does an important job. A water tower keeps water flowing to homes even when the pumps are resting.

The key idea behind a water tower is gravity. Water that is stored high above the ground presses down on the water below it. This pressing force, called water pressure, pushes water through the underground pipes and up into sinks and showers. The higher the water sits, the harder it pushes. That is why towers are usually built on the highest ground available.

The tower is filled in a regular cycle. At night, when most people are asleep, few faucets are running. Pumps use this quiet time to move water from a treatment plant up into the tank. During the morning rush, when families shower and cook breakfast, people use water faster than the pumps can supply it. The tower makes up the difference by letting stored water flow down into the pipes. By evening the tank is lower, and the cycle begins again.

A water tower also acts as a backup. If the power fails and the pumps stop, the stored water can still reach homes for a while. Firefighters depend on this, because fire hydrants need strong, steady pressure. In this way, a simple tank on legs protects the whole town.$q$, 'draft')
on conflict (id) do update set title = excluded.title, body = excluded.body
where public.passages.status = 'draft';
